11	function getHostname(url: string): string {
12	  try {
13	    return new URL(url).hostname.replace(/^www\./, "");
14	  } catch {
15	    return "";
16	  }
17	}
18	
19	const LinkMetadataCard = ({ url, fallback }: LinkMetadataCardProps) => {
